head.b:skin:
/* Blogger Theme Variables */
body { margin:0; font-family:'Inter','Segoe UI',system-ui,sans-serif; background:#09090b; color:#fafafa; overflow-x:hidden; }
a { text-decoration:none; color:inherit; }

/* NAV */
.nav{position:fixed;top:0;left:0;right:0;z-index:100;padding:16px 40px;display:flex;align-items:center;justify-content:space-between;background:rgba(9,9,11,.85);backdrop-filter:blur(20px);border-bottom:1px solid rgba(63,63,70,.3)}
.nav-logo{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:800}
.nav-links{display:flex;gap:32px;font-size:14px;font-weight:500;color:#a1a1aa}
.nav-links a:hover{color:#fafafa}
.nav-cta{background:#6366f1;color:#fff;padding:10px 24px;border-radius:10px;font-size:13px;font-weight:600;transition:all .3s}
.nav-cta:hover{background:#818cf8;transform:translateY(-1px);box-shadow:0 8px 30px rgba(99,102,241,.4)}

/* HERO */
.hero{min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;padding:140px 40px 100px;position:relative;overflow:hidden}
.hero::before{content:'';position:absolute;top:-200px;left:50%;transform:translateX(-50%);width:800px;height:800px;background:radial-gradient(circle,rgba(99,102,241,.15) 0%,rgba(6,182,212,.08) 40%,transparent 70%);pointer-events:none}
.hero-badge{display:inline-flex;align-items:center;gap:8px;padding:6px 16px;border-radius:100px;border:1px solid rgba(99,102,241,.3);background:rgba(99,102,241,.08);font-size:13px;font-weight:500;color:#818cf8;margin-bottom:32px}
.hero-badge .dot{width:6px;height:6px;border-radius:50%;background:#10b981;animation:pulse 2s infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}
.hero h1{font-size:clamp(42px,6vw,80px);font-weight:900;line-height:1.05;max-width:900px;margin:0 auto}
.hero h1 .grad{background:linear-gradient(135deg,#818cf8,#06b6d4);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.hero p{font-size:19px;color:#a1a1aa;max-width:600px;margin:24px auto 40px;line-height:1.7}
.hero-btns{display:flex;gap:16px;justify-content:center;align-items:center;flex-wrap:wrap;margin-top:8px}
.btn-primary{background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;padding:14px 32px;border-radius:12px;font-size:15px;font-weight:700;border:none;cursor:pointer;transition:all .3s;display:inline-flex;align-items:center;justify-content:center;gap:8px;min-width:180px;min-height:48px;text-align:center;line-height:1.4}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 12px 40px rgba(99,102,241,.5)}
.btn-secondary{background:#18181b;color:#fafafa;padding:14px 32px;border-radius:12px;font-size:15px;font-weight:600;border:1px solid #3f3f46;cursor:pointer;transition:all .3s;display:inline-flex;align-items:center;justify-content:center;gap:8px;min-width:180px;min-height:48px;text-align:center;line-height:1.4}
.btn-secondary:hover{border-color:#6366f1;background:#27272a}
.hero-stats{display:flex;justify-content:center;gap:60px;margin-top:80px}
.stat{text-align:center}
.stat .num{font-size:36px;font-weight:800;background:linear-gradient(135deg,#818cf8,#06b6d4);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.stat .label{font-size:13px;color:#71717a;margin-top:4px;font-weight:500}

/* SECTIONS */
section{padding:120px 40px}
.section-label{font-size:13px;font-weight:600;color:#6366f1;text-transform:uppercase;letter-spacing:2px;margin-bottom:12px;text-align:center}
.section-title{font-size:clamp(32px,4vw,48px);font-weight:800;text-align:center;max-width:700px;margin:0 auto 20px;line-height:1.15}
.section-desc{font-size:17px;color:#a1a1aa;text-align:center;max-width:560px;margin:0 auto 60px;line-height:1.7}

/* FEATURES GRID */
.features-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;max-width:1200px;margin:0 auto}
.feature-card{background:#18181b;border:1px solid #3f3f46;border-radius:20px;padding:36px;transition:all .4s;position:relative;overflow:hidden}
.feature-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#6366f1,transparent);opacity:0;transition:opacity .4s}
.feature-card:hover{border-color:rgba(99,102,241,.3);transform:translateY(-4px);box-shadow:0 20px 60px rgba(0,0,0,.4)}
.feature-card:hover::before{opacity:1}
.feature-icon{width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;margin-bottom:20px;font-size:24px}
.fi-blue{background:rgba(99,102,241,.12);color:#818cf8}
.fi-cyan{background:rgba(6,182,212,.12);color:#22d3ee}
.fi-emerald{background:rgba(16,185,129,.12);color:#34d399}
.fi-amber{background:rgba(245,158,11,.12);color:#fbbf24}
.fi-rose{background:rgba(244,63,94,.12);color:#fb7185}
.fi-purple{background:rgba(139,92,246,.12);color:#a78bfa}
.feature-card h3{font-size:18px;font-weight:700;margin-bottom:10px}
.feature-card p{font-size:14px;color:#a1a1aa;line-height:1.7}

/* HOW IT WORKS */
.steps{display:flex;gap:40px;max-width:1100px;margin:0 auto;position:relative}
.steps::before{content:'';position:absolute;top:40px;left:80px;right:80px;height:2px;background:linear-gradient(90deg,#6366f1,#06b6d4,#10b981);opacity:.3}
.step{flex:1;text-align:center;position:relative}
.step-num{width:80px;height:80px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:800;margin:0 auto 24px;position:relative;z-index:1}
.sn-1{background:linear-gradient(135deg,rgba(99,102,241,.2),rgba(99,102,241,.05));border:2px solid rgba(99,102,241,.3);color:#818cf8}
.sn-2{background:linear-gradient(135deg,rgba(6,182,212,.2),rgba(6,182,212,.05));border:2px solid rgba(6,182,212,.3);color:#22d3ee}
.sn-3{background:linear-gradient(135deg,rgba(16,185,129,.2),rgba(16,185,129,.05));border:2px solid rgba(16,185,129,.3);color:#34d399}
.step h3{font-size:18px;font-weight:700;margin-bottom:8px}
.step p{font-size:14px;color:#a1a1aa;max-width:260px;margin:0 auto}

/* PRICING */
.pricing-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;max-width:1200px;margin:0 auto}
.price-card{background:#18181b;border:1px solid #3f3f46;border-radius:20px;padding:36px 28px;text-align:center;transition:all .4s;position:relative}
.price-card.featured{border-color:#6366f1;box-shadow:0 0 60px rgba(99,102,241,.15)}
.price-card.featured::after{content:'MOST POPULAR';position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;padding:4px 16px;border-radius:20px;font-size:11px;font-weight:700;letter-spacing:1px}
.price-card:hover{transform:translateY(-4px);border-color:rgba(99,102,241,.4)}
.price-name{font-size:18px;font-weight:700;margin-bottom:8px}
.price-amount{font-size:48px;font-weight:900;margin:16px 0 4px}
.price-amount .currency{font-size:22px;font-weight:600;vertical-align:super}
.price-period{font-size:14px;color:#71717a;margin-bottom:24px}
.price-features{text-align:left;margin:24px 0;padding:0;list-style:none}
.price-features li{padding:8px 0;font-size:13px;color:#a1a1aa;display:flex;align-items:center;gap:10px;border-bottom:1px solid rgba(63,63,70,.3)}
.price-features li:last-child{border-bottom:none}
.price-features .check{color:#10b981;font-weight:700;font-size:16px}
.price-btn{width:100%;padding:14px;border-radius:12px;font-size:14px;font-weight:600;border:none;cursor:pointer;transition:all .3s;margin-top:8px}
.price-btn-primary{background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff}
.price-btn-primary:hover{box-shadow:0 8px 30px rgba(99,102,241,.4);transform:translateY(-1px)}
.price-btn-outline{background:transparent;color:#fafafa;border:1px solid #3f3f46}
.price-btn-outline:hover{border-color:#6366f1;background:rgba(99,102,241,.05)}

/* FINGERPRINT SHOWCASE */
.showcase{max-width:1100px;margin:0 auto;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.showcase-text h2{font-size:40px;font-weight:800;margin-bottom:20px;line-height:1.15}
.showcase-text p{font-size:16px;color:#a1a1aa;margin-bottom:32px;line-height:1.8}
.showcase-list{list-style:none;padding:0}
.showcase-list li{display:flex;align-items:center;gap:14px;padding:12px 0;font-size:15px;color:#a1a1aa}
.showcase-list .icon{width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0}
.showcase-visual{background:#18181b;border:1px solid #3f3f46;border-radius:20px;padding:32px;position:relative;overflow:hidden}
.showcase-visual::before{content:'';position:absolute;top:-1px;left:0;right:0;height:2px;background:linear-gradient(90deg,#6366f1,#06b6d4)}
.fp-row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid rgba(63,63,70,.2)}
.fp-row:last-child{border-bottom:none}
.fp-label{font-size:12px;color:#71717a;text-transform:uppercase;letter-spacing:1px;font-weight:600}
.fp-value{font-size:13px;font-weight:600}
.fp-val-blue{color:#818cf8}
.fp-val-cyan{color:#22d3ee}
.fp-val-emerald{color:#34d399}
.fp-val-amber{color:#fbbf24}

/* TESTIMONIALS */
.testimonials{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;max-width:1200px;margin:0 auto}
.testimonial{background:#18181b;border:1px solid #3f3f46;border-radius:20px;padding:32px;transition:all .3s}
.testimonial:hover{border-color:rgba(99,102,241,.3)}
.testimonial-stars{color:#fbbf24;font-size:14px;margin-bottom:16px;letter-spacing:2px}
.testimonial-text{font-size:14px;color:#a1a1aa;line-height:1.8;margin-bottom:20px;font-style:italic}
.testimonial-author{display:flex;align-items:center;gap:12px}
.testimonial-avatar{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:16px}
.ta-1{background:rgba(99,102,241,.2);color:#818cf8}
.ta-2{background:rgba(6,182,212,.2);color:#22d3ee}
.ta-3{background:rgba(16,185,129,.2);color:#34d399}
.testimonial-name{font-size:14px;font-weight:600}
.testimonial-role{font-size:12px;color:#71717a}

/* CTA SECTION */
.cta-section{text-align:center;padding:120px 40px;position:relative}
.cta-section::before{content:'';position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:600px;height:600px;background:radial-gradient(circle,rgba(99,102,241,.12),transparent 70%);pointer-events:none}
.cta-section h2{font-size:clamp(36px,5vw,56px);font-weight:900;margin-bottom:20px}
.cta-section p{font-size:18px;color:#a1a1aa;max-width:500px;margin:0 auto 40px}
.cta-section .btn-primary{font-size:17px;padding:18px 48px;border-radius:16px}

/* FOOTER */
.footer{border-top:1px solid #3f3f46;padding:60px 40px;text-align:center}
.footer-links{display:flex;justify-content:center;gap:40px;margin-bottom:24px;font-size:14px;color:#a1a1aa}
.footer-links a:hover{color:#fafafa}
.footer-copy{font-size:13px;color:#71717a}

/* ANIMATIONS */
@keyframes fadeUp{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:translateY(0)}}
.hero>*{animation:fadeUp .8s ease-out both}
.hero>*:nth-child(2){animation-delay:.1s}
.hero>*:nth-child(3){animation-delay:.2s}
.hero>*:nth-child(4){animation-delay:.3s}
.hero>*:nth-child(5){animation-delay:.4s}

/* RESPONSIVE */
@media(max-width:1024px){.features-grid,.testimonials{grid-template-columns:repeat(2,1fr)}.pricing-grid{grid-template-columns:repeat(2,1fr)}.showcase{grid-template-columns:1fr}.steps{flex-direction:column;gap:40px}.steps::before{display:none}}
@media(max-width:640px){.features-grid,.pricing-grid,.testimonials{grid-template-columns:1fr}.hero-stats{flex-direction:column;gap:24px}.nav-links{display:none}.hero{padding:120px 20px 60px}section{padding:80px 20px}.hero-btns{flex-direction:column;align-items:center}.btn-primary,.btn-secondary{min-width:220px}}
